import {Linking} from 'react-native';
import {useEffect} from 'react';
export function useDeepLink(handler:(path:string)=>void){
  useEffect(()=>{
    const parse=(u:string|null)=>{if(!u)return;const m=u.match(/{{scheme}}:\/\/{{host}}\/(.*)/);if(m)handler(m[1]);};
    Linking.getInitialURL().then(parse);
    const sub=Linking.addEventListener('url',e=>parse(e.url));
    return()=>sub.remove();
  },[handler]);}
